// desktop/native/gather-app/Tests/GatherAppTests/SessionNameAutoFillTests.swift
// 新建工作区名称自动填充：选目录/手改/切来源的状态机回归。
//
// 状态机有三条不变量（见 NewSessionSheet.swift 的 SessionNameAutoFill 文档）：
// 名称为空允许自动填充；用户手改过的非空名称永不被覆盖；名称仍是上次自动值且
// 用户没动过时随目录名更新。用例按不变量分组，避免"两个用例断言逐字相同"。
import Testing
@testable import GatherUI

@Suite("新建工作区名称自动填充")
struct SessionNameAutoFillTests {
    // MARK: - 选目录

    @Test("首次选目录填入目录名")
    func firstFolderFills() {
        var state = SessionNameAutoFill()
        #expect(state.apply(folderName: "A", currentName: "") == "A")
        #expect(state.lastAutoGeneratedName == "A")
        #expect(state.hasUserEdited == false)
    }

    @Test("再次选目录覆盖上一次自动名")
    func secondFolderOverwritesAuto() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        #expect(state.apply(folderName: "B", currentName: "A") == "B")
        #expect(state.lastAutoGeneratedName == "B")
    }

    @Test("选中同一目录不产生变更")
    func sameFolderReselectKeepsName() {
        var state = SessionNameAutoFill()
        #expect(state.apply(folderName: "A", currentName: "") == "A")
        #expect(state.apply(folderName: "A", currentName: "A") == "A")
        #expect(state.lastAutoGeneratedName == "A")
    }

    @Test("空目录名不做任何推断")
    func emptyFolderNameIsIgnored() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        #expect(state.apply(folderName: "", currentName: "A") == nil)
        #expect(state.apply(folderName: "", currentName: "") == nil)
        #expect(state.lastAutoGeneratedName == "A")
        #expect(state.hasUserEdited == false)
    }

    // MARK: - 手改

    @Test("手改后不再覆盖")
    func userEditStopsAuto() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        state.userEdited()
        #expect(state.apply(folderName: "B", currentName: "Custom") == nil)
        #expect(state.lastAutoGeneratedName == "A")
        #expect(state.hasUserEdited)
    }

    @Test("手改回与自动名相同也视为用户选择")
    func editBackToAutoNameStillStopsAuto() {
        // 与上一条的差别：这里是"名称逐字等于上一次自动值"的等值分支——
        // 旧实现靠清空 lastAuto 表达已编辑，这一分支根本走不到。
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        state.userEdited()
        #expect(state.apply(folderName: "B", currentName: "A") == nil)
        #expect(state.lastAutoGeneratedName == "A")
    }

    @Test("手改后清空名称，再选目录可恢复自动")
    func clearAfterEditAllowsAuto() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        state.userEdited()
        #expect(state.apply(folderName: "B", currentName: "") == "B")
        // 自动值重新接管：之后换目录应当继续跟随。
        #expect(state.hasUserEdited == false)
        #expect(state.apply(folderName: "C", currentName: "B") == "C")
    }

    // MARK: - 来源切换

    @Test("切到 Capture One 清空自动名，切回本地恢复")
    func sourceSwitchRestoresAutoName() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        #expect(state.sourceChanged(toLocal: false, currentName: "A", folderName: "A") == "")
        #expect(state.lastAutoGeneratedName.isEmpty)
        #expect(state.sourceChanged(toLocal: true, currentName: "", folderName: "A") == "A")
        #expect(state.lastAutoGeneratedName == "A")
    }

    @Test("自定义名称切换来源时保留")
    func customNameSurvivesSourceSwitch() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        state.userEdited()
        #expect(state.sourceChanged(toLocal: false, currentName: "Custom", folderName: "A") == nil)
        #expect(state.sourceChanged(toLocal: true, currentName: "Custom", folderName: "A") == nil)
        #expect(state.lastAutoGeneratedName == "A")
    }

    @Test("没有目录时不恢复空名称")
    func sourceSwitchWithoutFolderDoesNothing() {
        var state = SessionNameAutoFill()
        #expect(state.sourceChanged(toLocal: true, currentName: "", folderName: "") == nil)
    }

    @Test("名称只有空白时按空处理")
    func whitespaceOnlyNameCountsAsEmpty() {
        // 三处判定（apply / 切回本地 / 切离本地）必须同一口径，否则 "   " 会在
        // 一处被当成"已命名"、在另一处被当成"空"。
        var state = SessionNameAutoFill(lastAutoGeneratedName: "A")
        #expect(state.apply(folderName: "B", currentName: "   ") == "B")
        #expect(state.sourceChanged(toLocal: true, currentName: "   ", folderName: "C") == "C")
        #expect(state.sourceChanged(toLocal: false, currentName: "   ", folderName: "C") == "")
    }

    // MARK: - 初始目录（sheet 带 initialFolderPath 打开）

    @Test("带初始目录打开：换目录仍然跟随")
    func initialFolderCanBeReplaced() {
        var state = SessionNameAutoFill(lastAutoGeneratedName: "Init")
        #expect(state.apply(folderName: "Other", currentName: "Init") == "Other")
        #expect(state.lastAutoGeneratedName == "Other")
    }
}
